<?php
$pdo = db();
$counts = $pdo->query("SELECT COUNT(*) total, SUM(status='new') new_count, SUM(status='review') review_count, SUM(status='shortlisted') shortlisted_count, SUM(status='approved') approved_count, SUM(status='rejected') rejected_count FROM applications")->fetch();
$recent = $pdo->query('SELECT id, reference, first_name, last_name, project_name, sector, amount_requested, currency, status, created_at FROM applications ORDER BY created_at DESC LIMIT 8')->fetchAll();
$monthly = $pdo->query("SELECT DATE_FORMAT(created_at, '%Y-%m') label, COUNT(*) total FROM applications WHERE created_at >= DATE_SUB(CURDATE(), INTERVAL 12 MONTH) GROUP BY label ORDER BY label")->fetchAll();
$sectors = $pdo->query('SELECT sector label, COUNT(*) total FROM applications GROUP BY sector ORDER BY total DESC LIMIT 8')->fetchAll();
$countries = $pdo->query("SELECT COALESCE(NULLIF(project_country,''), country) label, COUNT(*) total FROM applications GROUP BY label ORDER BY total DESC LIMIT 8")->fetchAll();
$amounts = $pdo->query('SELECT currency label, SUM(amount_requested) requested, SUM(COALESCE(amount_approved,0)) approved FROM applications GROUP BY currency ORDER BY currency')->fetchAll();
$labels = status_labels();
?>
