<main class="admin-main"><?php render_admin_flash(); ?><header class="admin-top"><div><p class="eyebrow eyebrow-dark"><span></span>ESPACE ADMINISTRATEUR</p><h1>Bonjour, <?= e($_SESSION['admin_name'] ?? 'Administrateur') ?></h1><p>Voici l’activité récente du programme.</p></div><a class="button button-green" href="<?= e(url('admin-applications')) ?>">Voir les candidatures <i class="bi bi-arrow-right"></i></a></header>
<section class="stat-grid"><?php foreach ([['Total des dossiers',$counts['total']??0,'bi-collection'],['Nouvelles candidatures',$counts['new_count']??0,'bi-inbox'],['En étude',$counts['review_count']??0,'bi-search'],['Présélectionnées',$counts['shortlisted_count']??0,'bi-star'],['Approuvées',$counts['approved_count']??0,'bi-check-circle'],['Refusées',$counts['rejected_count']??0,'bi-x-circle']] as [$label,$num,$icon]): ?><article class="stat-card"><i class="bi <?= e($icon) ?>"></i><span><?= e((string)$num) ?></span><small><?= e($label) ?></small></article><?php endforeach; ?></section>
<section class="chart-grid"><article class="admin-panel chart-card"><h2>Candidatures par mois</h2><canvas id="monthly-chart" aria-label="Candidatures par mois"></canvas></article><article class="admin-panel chart-card"><h2>Candidatures par secteur</h2><canvas id="sector-chart" aria-label="Candidatures par secteur"></canvas></article><article class="admin-panel chart-card"><h2>Candidatures par pays</h2><canvas id="country-chart" aria-label="Candidatures par pays"></canvas></article><article class="admin-panel chart-card"><h2>Montants par devise</h2><canvas id="amount-chart" aria-label="Montants demandés et approuvés par devise"></canvas><p class="chart-note">Les montants ne sont comparés qu’au sein de chaque devise.</p></article></section>
<section class="admin-panel"><div class="panel-heading"><div><h2>Candidatures récentes</h2><p>Les dossiers les plus récemment soumis.</p></div><a class="text-link" href="<?= e(url('admin-applications')) ?>">Tous les dossiers <i class="bi bi-arrow-right"></i></a></div><?php if (!$recent): ?><div class="empty-state"><i class="bi bi-inbox"></i><h3>Aucune candidature pour le moment</h3><p>Les nouvelles candidatures apparaîtront ici.</p></div><?php else: ?><div class="table-scroll"><table class="data-table"><thead><tr><th>Référence</th><th>Candidat</th><th>Projet</th><th>Secteur</th><th>Montant demandé</th><th>Statut</th><th>Date</th></tr></thead><tbody><?php foreach ($recent as $row): ?><tr><td><a href="<?= e(url('admin-application',['id'=>$row['id']])) ?>"><?= e($row['reference']) ?></a></td><td><?= e($row['first_name'].' '.$row['last_name']) ?></td><td><?= e($row['project_name']) ?></td><td><?= e($row['sector']) ?></td><td><?= e(number_format((float)$row['amount_requested'],0,',',' ')) ?> <?= e($row['currency']) ?></td><td><span class="status-pill"><?= e($labels[$row['status']]??$row['status']) ?></span></td><td><?= e(date('d/m/Y',strtotime($row['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?></section>
<footer class="admin-footer">Les indicateurs reflètent les dossiers enregistrés. Ils ne préjugent pas de l’attribution d’un financement.</footer></main><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script>
const chartText={total:'Candidatures',requested:'Demandés',approved:'Approuvés'};
const monthly=<?= json_encode($monthly, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
const sectors=<?= json_encode($sectors, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
const countries=<?= json_encode($countries, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
const amounts=<?= json_encode($amounts, JSON_HEX_TAG|JSON_HEX_APOS|JSON_HEX_AMP|JSON_HEX_QUOT) ?>;
const green='#05cf70', navy='#211f3b', blue='#9692d4';
const common={responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true,grid:{color:'#eff0f2'}}}};
if(window.Chart){
 new Chart(document.getElementById('monthly-chart'),{type:'line',data:{labels:monthly.map(x=>x.label),datasets:[{label:chartText.total,data:monthly.map(x=>Number(x.total)),borderColor:green,backgroundColor:'rgba(5,207,112,.12)',fill:true,tension:.3}]},options:common});
 new Chart(document.getElementById('sector-chart'),{type:'doughnut',data:{labels:sectors.map(x=>x.label),datasets:[{data:sectors.map(x=>Number(x.total)),backgroundColor:[green,navy,blue,'#f3bc64','#54a6c7','#ed857b','#b4d96e','#a7a7ad']}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{position:'bottom'}}}});
 new Chart(document.getElementById('country-chart'),{type:'bar',data:{labels:countries.map(x=>x.label),datasets:[{label:chartText.total,data:countries.map(x=>Number(x.total)),backgroundColor:green,borderRadius:5}]},options:common});
 new Chart(document.getElementById('amount-chart'),{type:'bar',data:{labels:amounts.map(x=>x.label),datasets:[{label:chartText.requested,data:amounts.map(x=>Number(x.requested)),backgroundColor:navy,borderRadius:5},{label:chartText.approved,data:amounts.map(x=>Number(x.approved)),backgroundColor:green,borderRadius:5}]},options:common});
}
</script></body></html>
